//! Keys are the official `data-nav-anchor-key`s; values are the capture's and are bound to user settings by key.

use super::Page;
use super::model::{ButtonKind, Node, RadioOption};

pub(in crate::ui) fn nodes(page: Page) -> &'static [Node] {
    match page {
        Page::DataPrivacy => DATAPRIVACY,
        Page::MessagingPermissions => MESSAGINGPERMISSIONS,
        Page::Notifications => NOTIFICATIONS,
        Page::Nitro => NITRO,
        Page::ServerBoost => SERVERBOOST,
        Page::Subscriptions => SUBSCRIPTIONS,
        Page::GiftInventory => GIFTINVENTORY,
        Page::Billing => BILLING,
        Page::VoiceVideo => VOICEVIDEO,
        Page::Appearance => APPEARANCE,
        Page::Accessibility => ACCESSIBILITY,
        Page::System => SYSTEM,
        Page::LanguageTime => LANGUAGETIME,
        Page::RegisteredGames => REGISTEREDGAMES,
        Page::ActivityPrivacy => ACTIVITYPRIVACY,
        Page::GameOverlay => GAMEOVERLAY,
        Page::ConnectedApps => CONNECTEDAPPS,
        Page::Developer => DEVELOPER,
        _ => &[],
    }
}

